/// The orders of the model, as (loader first?, the loader's queries, the context's queries, interleaved?).
fn orders() -> Vec<(&'static str, Vec<usize>, Vec<usize>, bool, bool)> {
    let n = queries().len();
    let forward: Vec<usize> = (0..n).collect();
    let backward: Vec<usize> = (0..n).rev().collect();
    // `types_first` before `main` within each consumer.
    let mut types_first: Vec<usize> = forward.iter().copied().filter(|i| i % 2 == 1).collect();
    types_first.extend(forward.iter().copied().filter(|i| i % 2 == 0));
    vec![
        ("loader first", forward.clone(), forward.clone(), true, false),
        ("context first", forward.clone(), forward.clone(), false, false),
        ("interleaved", forward.clone(), backward.clone(), true, true),
        ("interleaved, context first", backward, forward.clone(), false, true),
        ("types_first first", types_first.clone(), types_first, true, true),
    ]
}

/// The arrangement before resolver sharing (the oracle): each consumer has a fresh `main` and a fresh `types_first`,
/// and the context checks the governing tsconfig on its fresh `main` before it resolves anything. Its answers to one
/// consumer's queries depend on that consumer's queries alone.
fn oracle(options: &PipelineOptions, root: &camino::Utf8Path, order: &[usize], context: bool) -> Vec<String> {
    let main_options = super::resolve_options(options);
    let types_first_options = oxc_resolver::ResolveOptions {
        condition_names: std::iter::once("types".into()).chain(super::custom_conditions(options)).collect(),
        ..main_options.clone()
    };
    let main = oxc_resolver::Resolver::new(main_options);
    let types_first = oxc_resolver::Resolver::new(types_first_options);
    if context && let Some(path) = super::governing_tsconfig(options) {
        let _ = main.resolve_tsconfig(path.as_std_path());
    }
    let queries = queries();
    order
        .iter()
        .map(|&i| {
            let (kind, importer, specifier) = queries[i];
            answer(if kind == Kind::Main { &main } else { &types_first }, root, importer, specifier)
